conv_transpose3d_kernel_source = """
__global__ void conv_transpose3d_kernel(
    const float* input_ptr,
    float* output_ptr,
    int B,          // batch size
    int C_in,       // in_channels
    int C_out,      // out_channels
    int out_D,      // output depth
    int out_H,      // output height
    int out_W,      // output width
    int kd,         // kernel size (square)
    int s,          // stride
    int p,          // padding (applied to input side)
    int op,         // output_padding
    int d,          // dilation
    int g,          // groups
    bool bias
) {
    const int total_output_elements = B * C_out * out_D * out_H * out_W;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_output_elements) return;

    // Decompose idx into (b, oc, od, oh, ow)
    int tmp = idx;
    int b = tmp / (C_out * out_D * out_H * out_W);
    tmp %= (C_out * out_D * out_H * out_W);
    int oc = tmp / (out_D * out_H * out_W);
    tmp %= (out_D * out_H * out_W);
    int od = tmp / (out_H * out_W);
    tmp %= (out_H * out_W);
    int oh = tmp / out_W;
    int ow = tmp % out_W;

    // Input flat index (stride=1, padding=0, dilation=1 → same indices)
    int input_idx = ((b * C_in + oc) * out_D * out_H * out_W +
                     od * out_H * out_W +
                     oh * out_W +
                     ow);
    output_ptr[idx] = input_ptr[input_idx];
}
"""

