class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias
        # Register the custom CUDA function for transposed 3D convolution
        self.conv_transpose3d_cuda = conv_transpose3d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: Input tensor of shape (batch_size, in_channels, depth, height, width)
        Returns:
            Output tensor of shape (batch_size, out_channels, depth_out, height_out, width_out)
        """
        # Cast to float for custom CUDA
        x_float = x.toFloat()
        # Call the custom transposed convolution
        return self.conv_transpose3d_cuda(x_float, self.out_channels)
